svg.metadata:
flowchart TB
  A["Authenticate identity; ai.acp.scoped(identity)"]
  B["Validate agent, model, workspace and execution policy"]
  C["Runner accepts durably; assign taskId / event sequence"]
  D["Obtain the configured worker; start or reuse native session"]
  E["Persist events and results; same identity resumes reading"]
  F["Check terminal state and cleanup; publish only after approval"]
  X["Authorization / execution / cleanup failure: report actual state"]
  A --> B
  B --> C
  C --> D
  D --> E
  E --> F
  B -->|"denied"| X
  D -->|"failed / unknown outcome"| X
  classDef default fill:#edf3ff,stroke:#476aab,color:#172b4d,stroke-width:1.5px;
  classDef good fill:#e9f6ef,stroke:#28734e,color:#17452f,stroke-width:1.5px;
  classDef stop fill:#fff0f0,stroke:#af4040,color:#742b2b,stroke-width:1.5px;
  classDef pending fill:#fff6df,stroke:#a07827,color:#654b18,stroke-width:1.5px;
  class F good;
  class X stop;
  class C pending;
